static NSUInteger checks;
static void Check(BOOL yes,NSString *name){checks++;if(!yes){NSLog(@"FAIL %@",name);exit(1);}NSLog(@"PASS %@",name);}
@implementation UIApplication
+ (UIApplication *)sharedApplication{static UIApplication *app;static dispatch_once_t once;dispatch_once(&once,^{app=[self new];app.expirations=[NSMutableDictionary new];});return app;}
- (UIBackgroundTaskIdentifier)beginBackgroundTaskWithName:(NSString *)name expirationHandler:(void (^)(void))handler{self.counter++;self.expirations[@(self.counter)]=handler;return self.counter;}
- (void)endBackgroundTask:(UIBackgroundTaskIdentifier)task{Check(self.expirations[@(task)]!=nil,@"short lease ended once");[self.expirations removeObjectForKey:@(task)];self.ended++;}
@end
@implementation BGTask
- (void)setTaskCompletedWithSuccess:(BOOL)success{Check(!self.completed,@"native task completed once");self.completed=YES;self.success=success;}
@end
@implementation BGContinuedProcessingTask
- (instancetype)init{if((self=[super init]))_progress=[NSProgress progressWithTotalUnitCount:1];return self;}
- (void)updateTitle:(NSString *)title subtitle:(NSString *)subtitle{self.title=title;self.subtitle=subtitle;}
@end
@implementation BGContinuedProcessingTaskRequest
- (instancetype)initWithIdentifier:(NSString *)i title:(NSString *)t subtitle:(NSString *)s{if((self=[super init])){_identifier=i;_title=t;_subtitle=s;}return self;}
@end
@implementation BGTaskScheduler
+ (BGTaskScheduler *)sharedScheduler{static BGTaskScheduler *s;static dispatch_once_t once;dispatch_once(&once,^{s=[self new];});return s;}
- (BOOL)registerForTaskWithIdentifier:(NSString *)i usingQueue:(dispatch_queue_t)q launchHandler:(void (^)(BGTask *))h{self.registrations++;self.handler=h;return !self.denyRegistration;}
- (void)cancelTaskRequestWithIdentifier:(NSString *)i{self.cancellations++;}
